package core

import (
	"database/sql/driver"
	"fmt"

	"github.com/google/uuid"
)

// ID is the identifier of a row of kind K: a UUIDv7 generated by the server
// (domain §2.1). K is a marker type that makes the identifiers of different
// entities distinct Go types, so a [CustomerID] cannot be passed where an
// [InvoiceID] is expected. The zero ID is the nil UUID and means "unset".
//
// The exported aliases ([CustomerID], [InvoiceID], …) are the types to use;
// [NewID] and [ParseID] create them.
type ID[K any] struct{ u uuid.UUID }

// IDFromUUID wraps u as an identifier of kind K.
func IDFromUUID[K any](u uuid.UUID) ID[K] { return ID[K]{u} }

// identifier is satisfied by every ID[K]; it lets [NewID] and [ParseID]
// return the alias the caller names.
type identifier[I any] interface {
	comparable
	withUUID(u uuid.UUID) I
}

func (id ID[K]) withUUID(u uuid.UUID) ID[K] { return ID[K]{u} }

// Identifier is satisfied by every identifier alias ([CustomerID], …); it
// lets code outside this package write functions generic over identifiers
// that call [ParseID] or [NewID].
type Identifier[I any] interface {
	identifier[I]
	// UUID returns the underlying UUID.
	UUID() uuid.UUID
}

// NewID returns a fresh identifier of type I from g:
//
//	id := core.NewID[core.CustomerID](gen)
func NewID[I identifier[I]](g IDGenerator) I {
	var zero I
	return zero.withUUID(g.NewUUID())
}

// ParseID parses the canonical textual form of a UUID into an identifier of
// type I.
func ParseID[I identifier[I]](s string) (I, error) {
	var zero I
	u, err := uuid.Parse(s)
	if err != nil {
		return zero, fmt.Errorf("parse id %q: %w", s, err)
	}
	return zero.withUUID(u), nil
}

// MustParseID is [ParseID] that panics on error; for tests and constants.
func MustParseID[I identifier[I]](s string) I {
	id, err := ParseID[I](s)
	if err != nil {
		panic(err)
	}
	return id
}

// UUID returns the underlying UUID.
func (id ID[K]) UUID() uuid.UUID { return id.u }

// IsZero reports whether id is unset.
func (id ID[K]) IsZero() bool { return id.u == uuid.Nil }

// String returns the canonical textual form of the UUID, or "" when unset.
func (id ID[K]) String() string {
	if id.IsZero() {
		return ""
	}
	return id.u.String()
}

// Compare orders identifiers by their bytes, which for UUIDv7 is creation
// order. It returns -1, 0 or +1.
func (id ID[K]) Compare(other ID[K]) int {
	for i := range id.u {
		switch {
		case id.u[i] < other.u[i]:
			return -1
		case id.u[i] > other.u[i]:
			return 1
		}
	}
	return 0
}

// MarshalText implements encoding.TextMarshaler; an unset ID encodes as "".
func (id ID[K]) MarshalText() ([]byte, error) { return []byte(id.String()), nil }

// UnmarshalText implements encoding.TextUnmarshaler; "" decodes as unset.
func (id *ID[K]) UnmarshalText(b []byte) error {
	if len(b) == 0 {
		*id = ID[K]{}
		return nil
	}
	u, err := uuid.ParseBytes(b)
	if err != nil {
		return fmt.Errorf("parse id %q: %w", b, err)
	}
	id.u = u
	return nil
}

// Value implements driver.Valuer; an unset ID is NULL.
func (id ID[K]) Value() (driver.Value, error) {
	if id.IsZero() {
		return nil, nil
	}
	return id.u.String(), nil
}

// Scan implements sql.Scanner; NULL scans as unset.
func (id *ID[K]) Scan(src any) error {
	if src == nil {
		*id = ID[K]{}
		return nil
	}
	var u uuid.UUID
	if err := u.Scan(src); err != nil {
		return fmt.Errorf("scan id: %w", err)
	}
	id.u = u
	return nil
}
